mapper.sql:
WHERE item.course_id = #{courseId}

  AND item.content ILIKE CONCAT('%', #{query}, '%')


  AND item.status = #{status, javaType=edu.ai.lms.core.quiz.app.domain.questionbank.QuestionBankItemStatus, typeHandler=org.apache.ibatis.type.EnumTypeHandler}


  AND item.chapter_id = #{chapterId}


  AND item.ccct_item_id = #{ccctItemId}


  AND EXISTS (
    SELECT 1 FROM edu.question_bank_item_learning_outcomes link
    WHERE link.question_bank_item_id = item.id
      AND link.learning_outcome_id = #{learningOutcomeId}
  )


  AND item.question_type = #{questionType, javaType=edu.ai.lms.core.quiz.app.domain.Question$QuestionType, typeHandler=org.apache.ibatis.type.EnumTypeHandler}


  AND item.source_type = #{sourceType, javaType=edu.ai.lms.core.quiz.app.domain.questionbank.QuestionBankSourceType, typeHandler=org.apache.ibatis.type.EnumTypeHandler}

mapper.select:
SELECT CASE WHEN EXISTS (
  SELECT 1
  FROM edu.question_bank_items item
  WHERE item.course_id = #{courseId}
    AND LOWER(BTRIM(item.content)) = LOWER(BTRIM(#{content}))
    AND item.status != 'ARCHIVED'

      AND item.id != #{excludedItemId}


      AND item.status = 'READY_FOR_USE'

) THEN 1 ELSE 0 END

mapper.update:
UPDATE edu.question_bank_items
SET status = 'READY_FOR_USE',
    ready_by = #{item.readyBy},
    ready_at = #{item.readyAt},
    version = version + 1,
    updated_at = NOW()
WHERE id = #{item.id}
  AND course_id = #{item.courseId}
  AND status = 'DRAFT'
  AND version = #{expectedVersion}

UPDATE edu.question_bank_items
SET status = 'ARCHIVED',
    version = version + 1,
    updated_at = NOW()
WHERE id = #{item.id}
  AND course_id = #{item.courseId}
  AND status = 'READY_FOR_USE'
  AND version = #{expectedVersion}

mapper.delete:
DELETE FROM edu.question_bank_items
WHERE id = #{item.id}
  AND course_id = #{item.courseId}
  AND status = 'DRAFT'
  AND version = #{expectedVersion}
